def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    strong_prev = []
    needy_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                needy_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 70:
                    strong_prev.append(float(bid))

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_prev = sorted_bids[int(1)]

    winners_est = max(1, int(float(supply) / WATER_REQ))
    tight_supply = winners_est <= 1
    very_tight = float(supply) <= 16.0
    abundant = float(supply) >= 24.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if tight_supply:
        urgency += 1
    if very_tight:
        urgency += 1
    if needy_count >= 2:
        urgency += 1
    if day >= 8:
        urgency += 1

    reserve = 0.0
    days_left = max(0, 10 - int(day))
    if hp > 4 and days_left > 0:
        reserve = min(budget * 0.35, days_left * 12.0)

    if urgency >= 5:
        target = max(92.0, highest_prev + 2.5)
    elif urgency >= 3:
        if highest_prev >= 85.0:
            target = highest_prev + 1.5
        else:
            target = max(74.0, highest_prev + 2.0)
    elif urgency >= 1:
        if abundant and hp >= 6:
            target = max(38.0, second_prev + 1.0)
        else:
            target = max(55.0, second_prev + 2.0)
    else:
        if abundant:
            target = 24.0
        elif tight_supply:
            target = 48.0
        else:
            target = 34.0

    if len(strong_prev) >= 2 and not abundant:
        target = max(target, second_prev + 1.5)

    if hp >= 8 and no_water_days == 0 and day <= 3 and highest_prev >= 95.0:
        target = min(target, 28.0)

    max_affordable = budget - reserve
    if urgency >= 4:
        max_affordable = budget
    if max_affordable < 0:
        max_affordable = 0.0

    bid = min(target, max_affordable)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 98.0 if tight_supply else 88.0))

    if budget < 25.0:
        bid = budget

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    alive_opps = []
    for opp_id, o in opponents_status.items():
        if o.get('alive', True):
            alive_opps.append((opp_id, o))

    # If no opponents, bid just enough to avoid no-water days.
    if not alive_opps:
        return max(0.0, min(my_status.get('budget', 0.0), DAILY_SALARY * 0.4))

    # Read yesterday's bids to infer pressure.
    yesterday_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    # Default baseline: moderate bid.
    base = DAILY_SALARY * 0.55

    # Pressure adjustment from yesterday.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If others were near my daily salary, they likely overbid for survival.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # If I'm healthy, undercut slightly; if low hp, match closer.
            if my_status.get('hp', 0) > 3:
                base = DAILY_SALARY * 0.35
            else:
                base = DAILY_SALARY * 0.85
        else:
            # Otherwise, bid slightly above the crowd average to secure water.
            avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))
            base = max(base, avg_prev + 2.0)

    # Supply-based urgency: if supply is tight relative to WATER_REQ, increase.
    # Expected number of water units is roughly supply / WATER_REQ.
    # Tight supply => fewer winners => bid more.
    if supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        base *= 1.10
    else:
        base *= 0.95

    # HP urgency: if I'm close to death, spend more.
    hp = float(my_status.get('hp', 0))
    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 4:
        base = max(base, DAILY_SALARY * 0.7)

    # Budget cap with a survival bias: keep some budget for later days.
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # If I've already missed water, increase bid to break the streak.
    if no_water_days >= 2:
        base *= 1.15

    # Keep a reserve: never bid more than ~70% of budget early, ~90% if late.
    # Episode days are 10; later days need more certainty.
    late_factor = 0.7
    if day >= 7:
        late_factor = 0.9
    elif day >= 4:
        late_factor = 0.8

    cap = budget * late_factor
    bid = min(cap, base)

    # Ensure non-negative and not exceeding daily salary by too much.
    # (Still allow higher if budget forces it.)
    if bid < 0.0:
        bid = 0.0

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_competitors = len(alive_opponents) + 1

    supply_units = int(current_supply // WATER_REQ)

    # 1. Survival Mode: If HP is low or no water days are accumulating, bid aggressively
    if my_status['hp'] <= 3 or my_status['no_water_days'] >= 1:
        bid_amount = min(my_status['budget'], DAILY_SALARY * 0.95)
        if current_day == EPISODE_DAYS and my_status['hp'] <= 3:
            bid_amount = my_status['budget']
        return bid_amount

    # 2. Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # 3. Determine competition intensity and adjust bid
    is_water_scarce = num_alive_competitors > supply_units

    if is_water_scarce:
        if yesterday_bids:
            avg_bid = sum(yesterday_bids) / len(yesterday_bids)
            bid_amount = max(DAILY_SALARY * 0.7, avg_bid + 2.0)
        else:
            bid_amount = DAILY_SALARY * 0.75
    else:
        if yesterday_bids:
            avg_bid = sum(yesterday_bids) / len(yesterday_bids)
            bid_amount = max(DAILY_SALARY * 0.4, avg_bid * 0.9)
            if my_status['hp'] > 5:
                bid_amount = max(DAILY_SALARY * 0.3, avg_bid * 0.8)
        else:
            bid_amount = DAILY_SALARY * 0.5

    final_bid = min(my_status['budget'], bid_amount)

    if final_bid <= 0 and my_status['budget'] > 0:
        final_bid = 1.0
    elif my_status['budget'] <= 0:
        final_bid = 0.0

    return final_bid
